{"cards": [{"node_code": "N_e36fb0c96c70dd28", "definition": "研究通过呼吸道途径传播的致病病毒的生物学特性、致病机制及诊断方法，涵盖流感、副流感、呼吸道合胞病毒、腺病毒及冠状病毒等。", "boundary": "本节点聚焦于以呼吸道为感染门户或主要靶器官的病毒。包括病毒在呼吸道的复制、传播动力学及特异性免疫反应。与肠道病毒的区别在于感染部位与传播途径；与肝炎病毒的区别在于靶器官。若内容侧重社区传播控制策略而非病毒本身特性，可关联传染病学，但病毒学基础归入本节点。", "includes": ["流感病毒、副流感病毒、呼吸道合胞病毒（RSV）的生物学与致病性", "腺病毒、鼻病毒及冠状病毒（如SARS-CoV-2）的结构与诊断技术"], "excludes": ["主要通过消化道传播的病毒（归入肠道病毒）", "主要侵犯肝脏的病毒（归入肝炎病毒）"], "sibling_distinctions": [{"other_code": "N_a47777dfb1f6fe1e", "rule": "呼吸道病毒以呼吸道黏膜为感染入口，经飞沫或气溶胶传播；肠道病毒以消化道为入口，经粪-口途径传播。"}, {"other_code": "N_7e5533ab0506013f", "rule": "呼吸道病毒主要引起呼吸系统症状；肝炎病毒主要侵犯肝脏，引起肝细胞损伤。"}], "cross_boundary_rule": "当内容涉及呼吸道病毒引起的具体肺炎或支气管炎临床诊疗时，若重点在于病原学鉴定与病毒特性，归入本节点；若重点在于临床分期、抗生素/抗病毒药物选择及重症监护，归入相应临床科室或传染病学。"}, {"node_code": "N_a47777dfb1f6fe1e", "definition": "研究经消化道传播、主要侵犯肠道或引起全身性疾病的致病病毒，包括脊髓灰质炎病毒、柯萨奇病毒、埃可病毒及诺如病毒等。", "boundary": "本节点聚焦于肠道病毒属（Enterovirus）及杯状病毒等经粪-口途径传播的病毒。涵盖病毒在肠道内的复制、病毒血症及向神经系统、心肌等靶器官的播散机制。与呼吸道病毒的区别在于传播途径与初始感染部位；与肝炎病毒的区别在于主要靶器官非肝脏。", "includes": ["脊髓灰质炎病毒、柯萨奇病毒、埃可病毒的分类与致病机制", "诺如病毒、轮状病毒等引起急性胃肠炎的病毒生物学特性"], "excludes": ["主要通过呼吸道飞沫传播的病毒（归入呼吸道病毒）", "主要引起慢性肝损伤的病毒（归入肝炎病毒）"], "sibling_distinctions": [{"other_code": "N_e36fb0c96c70dd28", "rule": "肠道病毒经粪-口途径传播，初始感染部位为肠道；呼吸道病毒经飞沫/气溶胶传播，初始感染部位为呼吸道。"}, {"other_code": "N_7e5533ab0506013f", "rule": "肠道病毒虽可经血液播散至多器官，但主要分类依据为肠道感染与传播；肝炎病毒专指主要侵犯肝脏的病毒。"}], "cross_boundary_rule": "若内容涉及肠道病毒引起的无菌性脑膜炎或心肌炎临床诊疗，重点在于病毒血清型鉴定与流行病学特征时归入本节点；若重点在于神经系统或心脏疾病的综合治疗，可关联相应临床科室。"}, {"node_code": "N_7e5533ab0506013f", "definition": "研究主要侵犯肝脏、引起病毒性肝炎的致病病毒，包括甲型、乙型、丙型、丁型及戊型肝炎病毒的生物学特性、致病机制及诊断。", "boundary": "本节点专攻嗜肝病毒。涵盖各型肝炎病毒的基因组结构、复制周期、肝细胞损伤机制及慢性化过程。与肠道病毒的区别在于靶器官特异性；与呼吸道病毒的区别在于传播途径与感染部位。包括疫苗预防策略及抗病毒治疗的基础原理。", "includes": ["甲型与戊型肝炎病毒的急性感染机制与预防", "乙型、丙型与丁型肝炎病毒的慢性感染、肝硬化及肝癌风险机制"], "excludes": ["非嗜肝病毒引起的肝脏损伤（如EB病毒、巨细胞病毒，通常归入疱疹病毒与逆转录病毒或其他）", "非病毒性肝炎（如酒精性、药物性肝炎）"], "sibling_distinctions": [{"other_code": "N_e36fb0c96c70dd28", "rule": "肝炎病毒主要靶器官为肝脏，传播途径多样（粪-口、血液、性接触等）；呼吸道病毒主要靶器官为呼吸系统，经呼吸道传播。"}, {"other_code": "N_a47777dfb1f6fe1e", "rule": "肝炎病毒专指嗜肝病毒；肠道病毒虽可经血液播散，但分类上不属于嗜肝病毒，主要引起肠道或全身性感染。"}], "cross_boundary_rule": "若内容涉及肝炎病毒引起的肝硬化、肝癌临床管理，重点在于病毒载量监测、基因分型及抗病毒药物机制时归入本节点；若重点在于外科手术、介入治疗或终末期肝病移植，归入相应临床科室。"}]}
